<script lang="ts">
  import {focusTrap} from '#lib/client/focus-trap.ts';
  import {onDestroy,onMount,untrack} from 'svelte';import {page} from '$app/state';import {refreshAll} from '$app/navigation';import {request,permitted} from '#lib/client/api.ts';import type {AppData,Row} from '#lib/client/types.ts';import Icon from './Icon.svelte';import ProposalPreview from './ProposalPreview.svelte';import AssistantSources from './AssistantSources.svelte';import {assistantRestrictedPaths,sourceReady,sourceReferences,type AssistantSource} from '#lib/client/assistant.ts';
  let {data}:{data:AppData}=$props();let open=$state(false);let deepReview=$state(false);let input=$state('');let error=$state('');let busy=$state(false);let recording=$state(false);let transcribing=$state(false);let messages:{role:'user'|'assistant';text:string;proposal?:Row;applied?:boolean;sources?:string[]}[]=$state([]);let recorder:MediaRecorder|null=null;let stream:MediaStream|null=null;let audio:BlobPart[]=[];let recordingTimeout:ReturnType<typeof setTimeout>;let cancelled=false;const proposalKeys=new Map<string,string>();
  let sources:AssistantSource[]=$state([]);let selectedElementIds:string[]=$state([]);let contextNotice=$state('');let lastContext='';
  const variantId=$derived(page.url.searchParams.get('variant')||data.summary?.selectedVariantId||data.related?.variants?.[0]?.id||undefined);
  const contextKey=$derived(data.path+':'+(data.detail?.id||'')+':'+(variantId||'')+':'+page.url.search);
  const sensitiveContext=$derived(!!data.module?.hr||data.module?.permission==='hr'||assistantRestrictedPaths.has((data.path||'').split('/')[0]));
  const designContext=$derived(data.path==='studio'||data.path?.startsWith('studio/')||data.module?.permission==='planning'||['planning','design','surveys'].some(section=>data.path?.startsWith(section)));
  const modelProfile=$derived(data.summary?.assistantModelProfile||{});
  const chosenProfile=$derived(designContext&&deepReview?modelProfile.design:modelProfile.standard);
  function dollars(value:unknown){return value===undefined||value===null||!Number.isFinite(Number(value))?'noch nicht bestätigt':new Intl.NumberFormat('de-DE',{style:'currency',currency:'USD',maximumFractionDigits:6}).format(Number(value));}
  $effect(()=>{const next=contextKey;untrack(()=>{if(next!==lastContext){contextNotice=lastContext?'Der Arbeitsbereich hat gewechselt. Unterlagen, Eingabe und vorherige Vorschläge wurden für den neuen Kontext geleert.':'';lastContext=next;sources=[];selectedElementIds=[];messages=[];input='';deepReview=false;error='';if(recording)stopRecording(true);}});});
  const integration=$derived(data.integrations?.ai||data.integrations?.openai);const available=$derived((integration?.available??false)&&!sensitiveContext);
  async function send(event:SubmitEvent){event.preventDefault();if(!input.trim()||busy||!available)return;const message=input.trim(),sendingContext=contextKey;error='';let references;try{references=sourceReferences(sources);}catch(cause){error=cause instanceof Error?cause.message:'Quellen prüfen.';return;}busy=true;messages=[...messages,{role:'user',text:message,sources:sources.map(source=>[source.name||'Ausgewählte Unterlage','Seite '+source.pageNumber,source.includeImage?'Text und vorbereitete Bildreferenz':'vorhandene Textauszüge'].join(' · '))}];try{const result=await request('/api/v1/ai/chat',{message,mode:designContext&&deepReview?'design_review':'standard',context:{path:data.path,variantId,search:page.url.search,...(designContext&&selectedElementIds.length?{selected_element_ids:selectedElementIds}:{})},references});if(sendingContext!==contextKey)return;if(typeof result?.text!=='string')throw new Error('Der Assistent hat keine lesbare Antwort geliefert.');messages=[...messages,{role:'assistant',text:result.text,proposal:result.proposal}];input='';}catch(cause){if(sendingContext===contextKey)error=cause instanceof Error?cause.message:'Die Anfrage konnte nicht abgeschlossen werden.';}finally{busy=false;}}
  async function apply(index:number){const message=messages[index];if(!message.proposal?.id||busy)return;busy=true;error='';try{const proposalId=message.proposal.id;const key=proposalKeys.get(proposalId)||crypto.randomUUID();proposalKeys.set(proposalId,key);await request(`/api/v1/ai/proposals/${proposalId}/apply`,{idempotencyKey:key});proposalKeys.delete(proposalId);messages=messages.map((m,i)=>i===index?{...m,applied:true}:m);await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Der Vorschlag konnte nicht angewendet werden. Prüfen Sie den aktuellen Stand.';}finally{busy=false;}}
  async function startRecording(){if(recording||busy||!available)return;error='';try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Dieser Browser unterstützt die Audioaufnahme nicht. Nutzen Sie die Texteingabe.');stream=await navigator.mediaDevices.getUserMedia({audio:true});audio=[];cancelled=false;const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,{...(mime?{mimeType:mime}:{}),audioBitsPerSecond:48000});recorder.ondataavailable=e=>{if(e.data.size)audio.push(e.data);if(audio.reduce((total,part)=>total+(part instanceof Blob?part.size:0),0)>2800000){error='Die Aufnahme ist zu groß. Verwenden Sie eine kürzere Aufnahme oder die Texteingabe.';stopRecording(true);}};recorder.onstop=async()=>{clearTimeout(recordingTimeout);stream?.getTracks().forEach(t=>t.stop());stream=null;recording=false;if(cancelled)return;transcribing=true;const transcribingContext=contextKey;try{const audioBlob=new Blob(audio,{type:recorder?.mimeType||'audio/webm'});if(audioBlob.size>2800000)throw new Error('Die Aufnahme ist zu groß. Bitte kürzer aufnehmen oder den Text eingeben.');const body=new FormData();body.append('audio',audioBlob,recorder?.mimeType.includes('mp4')?'aufnahme.m4a':'aufnahme.webm');const result=await request('/api/v1/ai/transcribe',body);if(typeof result?.text!=='string')throw new Error('Es wurde kein bearbeitbarer Text erkannt.');if(transcribingContext!==contextKey)return;input=input?`${input}\n${result.text}`:result.text;}catch(e){if(transcribingContext===contextKey)error=e instanceof Error?e.message:'Die Transkription ist fehlgeschlagen.';}finally{transcribing=false;audio=[];}};recorder.onerror=()=>{error='Die Audioaufnahme ist fehlgeschlagen. Nutzen Sie die Texteingabe.';stopRecording(true);};recorder.start(1000);recording=true;recordingTimeout=setTimeout(()=>stopRecording(),120000);}catch(e){error=e instanceof Error?e.message:'Der Mikrofonzugriff ist nicht verfügbar.';stream?.getTracks().forEach(t=>t.stop());stream=null;}}
  function stopRecording(cancel=false){cancelled=cancel;clearTimeout(recordingTimeout);if(recorder&&recorder.state!=='inactive')recorder.stop();else{stream?.getTracks().forEach(t=>t.stop());stream=null;recording=false;}}
  function close(){if(recording)stopRecording(true);open=false;}
  onMount(()=>{const show=()=>open=true;const selection=(event:Event)=>{const detail=(event as CustomEvent).detail;if(designContext&&detail?.variantId===variantId)selectedElementIds=[...new Set((detail.selectedElementIds||[]).filter((id:unknown)=>typeof id==='string'&&/^[a-f0-9-]{36}$/i.test(id)))].slice(0,20) as string[];};window.addEventListener('schubert:assistant:open',show);window.addEventListener('schubert:studio:selection',selection);return()=>{window.removeEventListener('schubert:assistant:open',show);window.removeEventListener('schubert:studio:selection',selection);};});
  onDestroy(()=>{cancelled=true;clearTimeout(recordingTimeout);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop());});
</script>
{#if !open}<button class="assistant-trigger" onclick={()=>open=true} aria-expanded="false" aria-controls="assistant-drawer"><Icon name="spark" size={17}/>Assistent</button>{:else}<div class="assistant-overlay" role="presentation" onclick={close}></div><div use:focusTrap id="assistant-drawer" class="assistant-drawer" role="dialog" aria-modal="true" aria-label="Schubert KI-Assistent" tabindex="-1" onkeydown={(e)=>{if(e.key==='Escape')close();}}><header class="assistant-header"><div class="empty-icon" style="width:35px;height:35px;margin:0"><Icon name="spark" size={18}/></div><div><h2>Ihr Assistent</h2><p>KI · im Kontext dieses Arbeitsbereichs</p></div><button class="icon-button" onclick={close} aria-label="Assistent schließen"><Icon name="close"/></button></header><div class="assistant-messages" aria-live="polite">{#if !available}<div class="notice warning"><Icon name="alert"/><div class="notice-content"><div class="notice-title">{sensitiveContext?'Lokale Feldhilfe für diesen Bereich':'Noch nicht verfügbar'}</div><p>{sensitiveContext?'Personal- und Administrationsakten bleiben außerhalb der KI. Die Hinweise direkt an den Eingabefeldern erklären die erforderlichen Angaben.':integration?.message||'Die OpenAI-Verbindung und das Modellprofil sind noch nicht eingerichtet.'}</p>{#if !sensitiveContext&&permitted(data,'admin')}<a class="text-link mt" href="/settings" onclick={close}>Integration prüfen<Icon name="arrow" size={14}/></a>{:else if !sensitiveContext}<p class="field-help mt">Die zuständige Administration kann die Verbindung in den Betriebseinstellungen einrichten.</p>{/if}</div></div>{/if}{#if contextNotice}<p class="field-help mb" role="status">{contextNotice}</p>{/if}{#if !messages.length&&!sensitiveContext}<div class="chat-message assistant"><div class="chat-role">Arbeiten mit dem Assistenten</div>Beschreiben Sie, was Sie erledigen möchten. Der Assistent verwendet nur Daten, auf die Sie zugreifen dürfen, und zeigt Änderungen vor der Anwendung.<p class="field-help mt">Zum Beispiel: „Was fehlt für die Freigabe dieses Auftrags?“ oder „Bereite einen Angebotsentwurf aus der Anfrage vor.“</p></div>{/if}{#each messages as message,index}<article class="chat-message {message.role}"><div class="chat-role">{message.role==='user'?'Sie':'Schubert Assistent · KI'}</div>{message.text}{#if message.sources?.length}<p class="field-help mt">Bewusst gewählte Quellen: {message.sources.join(' · ')}</p>{/if}{#if message.proposal}<div class="assistant-proposal"><h3>Änderungsvorschlag prüfen</h3>{#if message.proposal.target}<p>Bezug: {message.proposal.target.entityType} · Version {message.proposal.target.baseVersion}</p>{/if}{#if message.proposal.assumptions?.length}<p>Annahmen</p><ul>{#each message.proposal.assumptions as assumption}<li>{assumption}</li>{/each}</ul>{/if}{#if (message.proposal.missingInputs||message.proposal.missing_inputs)?.length}<p>Noch zu klären</p><ul>{#each message.proposal.missingInputs||message.proposal.missing_inputs||[] as missing}<li>{missing}</li>{/each}</ul>{/if}<ProposalPreview proposal={message.proposal} {data}/><details class="mt"><summary style="font-size:12px;cursor:pointer">Technische Details ansehen</summary><pre>{JSON.stringify(message.proposal.proposedCommands||message.proposal.commands||message.proposal.changes||{},null,2)}</pre></details>{#if message.proposal.validation?.blocking?.length}<div class="notice error mt">{message.proposal.validation.blocking.join(' · ')}</div>{/if}{#if message.applied}<p class="mt"><Icon name="check" size={13}/> Vom Server bestätigt angewendet.</p>{:else}<button class="btn primary full" onclick={()=>apply(index)} disabled={busy||message.proposal.validation?.blocking?.length||message.proposal.status==='expired'}>Geprüften Vorschlag anwenden</button>{/if}</div>{/if}</article>{/each}{#if busy}<p class="small muted"><Icon name="refresh" size={14} class="spin"/> Der Assistent arbeitet …</p>{/if}{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}</div><form class="assistant-input" onsubmit={send}><div class="assistant-compose-fields">{#if !sensitiveContext}<AssistantSources {data} bind:rows={sources} disabled={busy||recording||transcribing}/>{/if}{#if !sensitiveContext}<div class="assistant-model-choice">{#if designContext}<label class="check-field"><input type="checkbox" bind:checked={deepReview} disabled={busy||!available}/><span>Vertieft prüfen</span></label><p class="field-help">{deepReview?'Verwendet nach dem Senden das Modell für vertiefte Designprüfung. Das eigene Kostenlimit und das Monatsbudget gelten.':'Standardmodus mit dem günstigeren Modell. Für komplexe Planungsfragen können Sie eine vertiefte Prüfung bewusst auswählen.'}</p>{:else}<p class="field-help">Standardassistent · keine automatische Eskalation zu teureren Modellen.</p>{/if}{#if chosenProfile?.model}<p class="field-help mt">{chosenProfile.model} · höchstens {dollars(chosenProfile.maxRequestCost)} je Anfrage.</p><details class="mt"><summary class="field-help">Kostenrahmen ansehen</summary><p class="field-help mt">Je 1 Million Tokens: Eingabe {dollars(chosenProfile.inputCostPerMillion)}, Ausgabe {dollars(chosenProfile.outputCostPerMillion)}. Monatsbudget {dollars(modelProfile.monthlyBudget)}. Der Server reserviert die mögliche Obergrenze; abgerechnet wird der tatsächliche bestätigte Verbrauch.</p></details>{/if}{#if designContext&&selectedElementIds.length}<p class="field-help mt">Aktuell {selectedElementIds.length} ausgewählte Studiokomponente(n). Die gespeicherte Revision bleibt die Grundlage.</p>{/if}</div>{/if}<label class="sr-only" for="assistant-message">Nachricht an den Assistenten</label><textarea id="assistant-message" class="field-control" maxlength="6000" bind:value={input} placeholder={sensitiveContext?'Nutzen Sie die Hinweise an den Eingabefeldern.':available?'Was möchten Sie erledigen?':'Texteingabe nach Einrichtung verfügbar'} disabled={!available||busy||recording}></textarea>{#if recording}<div class="notice warning mt" role="status"><Icon name="mic" size={17}/><div>Aufnahme läuft. Stoppen Sie die Aufnahme, um den Text zu prüfen.</div></div>{/if}{#if transcribing}<p class="field-help mt" role="status">Audio wird transkribiert. Anschließend können Sie den Text bearbeiten.</p>{/if}</div><div class="assistant-input-actions">{#if recording}<div class="inline-actions"><button type="button" class="btn small danger" onclick={()=>stopRecording()}><Icon name="stop" size={15}/>Stoppen</button><button type="button" class="btn small ghost" onclick={()=>stopRecording(true)}>Verwerfen</button></div>{:else}<button type="button" class="btn small ghost" disabled={!available||busy||transcribing} onclick={startRecording}><Icon name="mic" size={17}/>Sprechen</button>{/if}<button class="btn primary" type="submit" disabled={!available||busy||recording||transcribing||!input.trim()||sources.some(source=>!sourceReady(source))}>Senden<Icon name="arrow" size={16}/></button></div><p class="field-help mt">Namen, Daten, Maße und Beträge vor der Anwendung prüfen. Sprache ist freiwillig; die manuelle Eingabe bleibt verfügbar.</p></form></div>{/if}

<style>.assistant-header{flex-shrink:0}.assistant-input{display:flex;flex-direction:column;flex-shrink:0;max-height:65dvh;overflow:hidden}.assistant-compose-fields{min-height:0;overflow-y:auto;overscroll-behavior:contain}.assistant-input-actions,.assistant-input>p{flex-shrink:0}.assistant-input-actions{padding-top:12px}.assistant-messages{min-height:90px}.assistant-model-choice details summary{cursor:pointer;min-height:30px}@media(max-width:760px){.assistant-input{max-height:calc(95dvh - 185px)}.assistant-model-choice details summary{min-height:40px}}</style>
